insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '34f98972-c1bc-50f6-ae86-a73cb0f46442', id, null, 15, '2', 'O que é uma pirâmide ecológica? Por que ela tem esse formato? Escolher um mamífero, um pássaro, um réptil e um anfíbio comuns na região em que você mora e construir para cada um deles um diagrama de sua pirâmide ecológica.', '2026-10-31 08:41:54', null from especialidades where codigo = 'EN-044' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
