insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'dc8ebde2-29bd-5c31-9dc7-259a5a51e2fc', id, null, 18, '5', 'Pesquisar sobre como se faz a coleta de lixo em seu bairro e qual o destino do lixo coletado. Elaborar um relatório com as informações de quanto lixo sua família joga por dia e como poderiam lidar melhor com isto.', '2026-10-31 08:41:54', null from especialidades where codigo = 'EN-044' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '91fdad3d-424b-54d3-940f-3a010f9e1511', id, null, 19, '6', 'Pesquisar nos jornais ou em algum site especializado, por uma semana, os níveis de poluição atmosférica de uma cidade grande (a mais perto da sua, se você não morar numa cidade grande). Fazer um gráfico demonstrando a curva deste nível durante semana. Descobrir o que causa os pontos altos de sua curva do gráfico.', '2026-10-31 08:41:54', null from especialidades where codigo = 'EN-044' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
