insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '31f8e434-63fa-5667-9f91-75fd39932303', id, 'd96beb3d-a501-5115-a266-6db3a33ac119', 20, '8.a', 'Escolher uma comunidade biológica de sua região como, por exemplo, uma floresta ou bosque, pântano, lago ou açude, pasto ou campo, desfiladeiro ou riacho, etc, que esteja de alguma forma alterado ecologicamente. Descrever o local, incluindo como se deu e até que ponto o equilíbrio foi alterado. Depois, apresentar recomendações sobre como aquela comunidade pode ser melhorada e direcionar seus esforços para o acompanhamento e ajuda no trabalho de melhoria;', '2026-09-23 11:54:47', null from especialidades where codigo = 'EN-045' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
